def run(ctx, args):
    best = ctx.best_score()
    budget = ctx.budget_left()
    remaining = budget.get("budget_left", 10)

    # Provide strategic guidance for circle packing
    if remaining <= 4:
        guidance = "Low budget: try hexagonal packing with large central circle (r~0.25) + 6 shell circles (r~0.12) + layered rows of smaller circles."
    elif remaining <= 8:
        guidance = "Medium budget: explore layered construction with alternating offsets. Try 7-6-7-6-7 row pattern with staggered horizontal positions."
    else:
        guidance = "Good budget: test multiple packing families - hexagonal shells, layered offsets, and corner-heavy arrangements."

    return {
        "best_score": best,
        "budget_left": remaining,
        "guidance": guidance
    }

